-- The built-in postgres and mysql Substrate start scripts mark their setup done (a file named by
-- WARDBY_SERVICE_SETUP_DONE, which the Substrate start script sets and waits for) as their last step,
-- so a service is ready only after createdb has run or the mysql user exists.
UPDATE "CodingService" SET "startCommand" = '["/bin/sh","-c","set -u; if [ ! -s \"$PGDATA/PG_VERSION\" ]; then pw=\"/tmp/.wardby-pgpw.$$\"; (umask 077 && printf ''%s\\n'' \"$POSTGRES_PASSWORD\" > \"$pw\") || exit 1; initdb -D \"$PGDATA\" -U \"$POSTGRES_USER\" --pwfile=\"$pw\" --auth-host=scram-sha-256 --auth-local=trust; rc=$?; rm -f \"$pw\"; [ \"$rc\" -eq 0 ] || exit \"$rc\"; fi; postgres -D \"$PGDATA\" -c listen_addresses=127.0.0.1 -c unix_socket_directories=/tmp & pid=$!; until pg_isready -q -h 127.0.0.1; do kill -0 \"$pid\" 2>/dev/null || exit 1; sleep 1; done; export PGPASSWORD=\"$POSTGRES_PASSWORD\"; psql -h 127.0.0.1 -U \"$POSTGRES_USER\" -d \"$POSTGRES_DB\" -Atc ''select 1'' >/dev/null 2>&1 || createdb -h 127.0.0.1 -U \"$POSTGRES_USER\" \"$POSTGRES_DB\" || exit 1; unset PGPASSWORD; : > \"$WARDBY_SERVICE_SETUP_DONE\" || exit 1; wait \"$pid\""]'::jsonb
  WHERE "builtin" = true AND "name" = 'postgres';
UPDATE "CodingService" SET "startCommand" = '["/bin/sh","-c","export PERCONA_TELEMETRY_DISABLE=1; set -u; O=\"--datadir=/var/lib/mysql/data --socket=/tmp/mysqld.sock --pid-file=/tmp/mysqld.pid --secure-file-priv=/tmp --log-error=/tmp/mysqld.err\"; init=0; if [ ! -d /var/lib/mysql/data/mysql ]; then mysqld $O --initialize-insecure || exit 1; init=1; fi; mysqld $O --bind-address=127.0.0.1 --port=3306 --mysqlx=OFF & pid=$!; until mysqladmin --socket=/tmp/mysqld.sock -uroot ping --silent >/dev/null 2>&1; do kill -0 \"$pid\" 2>/dev/null || exit 1; sleep 1; done; lit() { printf ''%s'' \"$1\" | sed -e ''s/\\\\/\\\\\\\\/g'' -e \"s/''/''''/g\"; }; if [ \"$init\" = 1 ]; then d=$(printf ''%s'' \"$MYSQL_DATABASE\" | sed ''s/`/``/g''); u=$(lit \"$MYSQL_USER\"); p=$(lit \"$MYSQL_PASSWORD\"); r=$(lit \"$MYSQL_ROOT_PASSWORD\"); printf ''%s\\n'' \"CREATE DATABASE IF NOT EXISTS \\`$d\\`;\" \"CREATE USER IF NOT EXISTS ''$u''@''%'' IDENTIFIED BY ''$p'';\" \"GRANT ALL ON \\`$d\\`.* TO ''$u''@''%'';\" \"ALTER USER ''root''@''localhost'' IDENTIFIED BY ''$r'';\" | mysql --socket=/tmp/mysqld.sock -uroot || exit 1; fi; : > \"$WARDBY_SERVICE_SETUP_DONE\" || exit 1; wait \"$pid\""]'::jsonb
  WHERE "builtin" = true AND "name" = 'mysql';
